import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { db } from '../config/firebase';
import { collection, getDocs } from 'firebase/firestore';
import './Dashboard.css';

const Dashboard = () => {
  const [stats, setStats] = useState({
    totalPanels: 0,
    activePanels: 0,
    maintenanceNeeded: 0,
    efficiency: 0
  });

  const [recentMaintenance, setRecentMaintenance] = useState([]);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      // Fetch maintenance records
      const maintenanceSnapshot = await getDocs(collection(db, 'maintenance_records'));
      const maintenanceData = maintenanceSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      // Calculate statistics
      const totalPanels = maintenanceData.length;
      const activePanels = maintenanceData.filter(panel => panel.status === 'active').length;
      const maintenanceNeeded = maintenanceData.filter(panel => panel.status === 'maintenance_needed').length;
      const efficiency = totalPanels > 0 ? (activePanels / totalPanels) * 100 : 0;

      setStats({
        totalPanels,
        activePanels,
        maintenanceNeeded,
        efficiency: efficiency.toFixed(1)
      });

      // Get recent maintenance records
      const recent = maintenanceData
        .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp))
        .slice(0, 5);
      setRecentMaintenance(recent);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    }
  };

  const StatCard = ({ title, value, icon, color }) => (
    <motion.div 
      className="stat-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      <div className="stat-icon" style={{ backgroundColor: color }}>
        {icon}
      </div>
      <div className="stat-content">
        <h3>{title}</h3>
        <p>{value}</p>
      </div>
    </motion.div>
  );

  return (
    <div className="dashboard-container">
      <h1>Dashboard Overview</h1>

      <div className="stats-grid">
        <StatCard
          title="Total Panels"
          value={stats.totalPanels}
          icon="🌞"
          color="#4CAF50"
        />
        <StatCard
          title="Active Panels"
          value={stats.activePanels}
          icon="⚡"
          color="#2196F3"
        />
        <StatCard
          title="Maintenance Needed"
          value={stats.maintenanceNeeded}
          icon="🔧"
          color="#FF9800"
        />
        <StatCard
          title="System Efficiency"
          value={`${stats.efficiency}%`}
          icon="📊"
          color="#9C27B0"
        />
      </div>

      <div className="recent-maintenance">
        <h2>Recent Maintenance</h2>
        <div className="maintenance-list">
          {recentMaintenance.map((record, index) => (
            <motion.div
              key={record.id}
              className="maintenance-item"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.1 }}
            >
              <div className="maintenance-info">
                <h3>Panel {record.panelId}</h3>
                <p>{record.description}</p>
              </div>
              <div className="maintenance-status">
                <span className={`status-badge ${record.status}`}>
                  {record.status}
                </span>
                <p className="maintenance-date">
                  {new Date(record.timestamp).toLocaleDateString()}
                </p>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
